INSERT INTO dishes (type_id, name, detail, cover_url, status, create_time) SELECT 1, '青椒肉丝', '鲜嫩肉丝搭配爽脆青椒，咸香下饭。', 'http://localhost:8081/uploads/青椒肉丝.jpg', 1, NOW() WHERE NOT EXISTS (SELECT 1 FROM dishes WHERE name = '青椒肉丝');
